local KTool = CS.Engine.Lib.KTool
local POOL_MAX = 0
local PoolManager   = CS.Engine.Lib.PoolManager
local CDTimerModule = CS.Engine.Modules.CDTimerModule

--- from: Assets/BundleResources/Prefabs/Common/CommonManegeRemind.prefab
---@class CommonManegeRemind
---@field Env                           	CommonManegeRemind                      
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Node                          	UnityEngine.RectTransform               
---@field TextDesc                      	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
local CommonManegeRemind = Class('CommonManegeRemind')
function CommonManegeRemind:__init()
    self.closeTimer_ = nil
    self.animeTimer_ = nil
end

function CommonManegeRemind:__delete()
    self.closeTimer_ = nil
    self.animeTimer_ = nil
end

function CommonManegeRemind:Awake()
    if not isNull(self) and not isNull(self.Node) then
        CfUtils.PlayAnimation(self.Node, 'CommonManegeRemind_Go')
    end
    self.exitGameEvent = Events.AddListener("RemoveMessageTipByExitGame",Bind(self,self.CloseDialog))
end

function CommonManegeRemind:ShowMessageInfo(id,time)
    if checkNumber(id) == 0 then return end
    self:SetNodeInfo(id)
    local closeInterval = checkInt(time)
    self.closeTimer_ = CDTimerModule.GetInstance():AddCD(closeInterval, function(i, t)
        if not isNull(self) and not isNull(self.controller) then
            PoolManager.Instance:GiveBack(self.controller.gameObject, POOL_MAX)
        end
    end)

    local exitAnimTime  = CfUtils.GetAnimationTime(self.Node, 'CommonManegeRemind_Hide')
    local doAnimIntaval = math.floor(math.max(closeInterval - exitAnimTime, 0))  -- cd 只能是 int 值，所以只能小数部分社区，提早播放动画
    self.animeTimer_ = CDTimerModule.GetInstance():AddCD(doAnimIntaval, function(i, t)
        if not isNull(self) and not isNull(self.Node) then
            CfUtils.PlayAnimation(self.Node, 'CommonManegeRemind_Hide')
        end
    end)
end

function CommonManegeRemind:CloseDialog()
    if not isNull(self) and not isNull(self.controller) then
        PoolManager.Instance:GiveBack(self.controller.gameObject, POOL_MAX)
    end
end

function CommonManegeRemind:SetNodeInfo(id)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6053,"MaidCoffeeTipVo",id)
    if not isNull(vo) then
        CfUtils.SetUISwitchImage(self.ImgIcon,vo.iconStatus)
        CfUtils.FillText(self.TextDesc,vo.decr)
    end
end

function CommonManegeRemind:Start()
end

function CommonManegeRemind:OnDestroy()
    ---加回到对象池中去
    if not isNull(self.closeTimer_) then
        CDTimerModule.GetInstance():RemoveCD(self.closeTimer_)
        self.closeTimer_ = nil
    end
    if not isNull(self.animeTimer_) then
        CDTimerModule.GetInstance():RemoveCD(self.animeTimer_)
        self.animeTimer_ = nil
    end

    if not isNull(self.exitGameEvent) then
        Events.RemoveListener("RemoveMessageTipByExitGame",self.exitGameEvent)
        self.exitGameEvent = nil
    end

    self:Delete()
    self.controller = nil--luabehaviour 中CSharp对象
    self = nil
end

return CommonManegeRemind